-- Only transaction-scoped management writes activate these bounded captures.
ALTER TABLE management_operations ADD COLUMN target_name TEXT NOT NULL DEFAULT '' CHECK(length(CAST(target_name AS BLOB))<=256);
ALTER TABLE management_operation_items ADD COLUMN details TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(details) AND json_type(details)='object' AND length(CAST(details AS BLOB))<=65536);
CREATE TABLE management_operation_terms (
 term TEXT NOT NULL CHECK(length(CAST(term AS BLOB))<=2048),
 operation_id INTEGER NOT NULL REFERENCES management_operations(id),
 ordinal INTEGER NOT NULL,
 PRIMARY KEY(term,operation_id,ordinal)
) STRICT, WITHOUT ROWID;
CREATE INDEX management_operation_terms_item ON management_operation_terms(operation_id,ordinal);
CREATE INDEX management_operation_items_name ON management_operation_items(target_name,operation_id);
CREATE TABLE management_capture_context (
 id INTEGER PRIMARY KEY CHECK(id=1),
 event_id TEXT NOT NULL CHECK(length(CAST(event_id AS BLOB))<=128)
) STRICT;
CREATE TABLE management_capture_rows (
 event_id TEXT NOT NULL,
 kind TEXT NOT NULL,
 target_id TEXT NOT NULL,
 before_json TEXT CHECK(before_json IS NULL OR (json_valid(before_json) AND length(CAST(before_json AS BLOB))<=131072)),
 after_json TEXT CHECK(after_json IS NULL OR (json_valid(after_json) AND length(CAST(after_json AS BLOB))<=131072)),
 facts_json TEXT NOT NULL CHECK(json_valid(facts_json) AND length(CAST(facts_json AS BLOB))<=8192),
 PRIMARY KEY(event_id,kind,target_id)
) STRICT, WITHOUT ROWID;
CREATE TABLE management_capture_totals (
 event_id TEXT NOT NULL,
 kind TEXT NOT NULL,
 created INTEGER NOT NULL DEFAULT 0,
 updated INTEGER NOT NULL DEFAULT 0,
 deleted INTEGER NOT NULL DEFAULT 0,
 omitted INTEGER NOT NULL DEFAULT 0,
 PRIMARY KEY(event_id,kind)
) STRICT, WITHOUT ROWID;

CREATE TRIGGER management_capture_discovery_runs_insert AFTER INSERT ON discovery_runs
WHEN EXISTS(SELECT 1 FROM management_capture_context)
BEGIN
 INSERT INTO management_capture_totals(event_id,kind,created) SELECT event_id,'discovery_runs',1 FROM management_capture_context WHERE id=1
 ON CONFLICT(event_id,kind) DO UPDATE SET created=created+1;
 UPDATE management_capture_totals SET omitted=omitted+1 WHERE event_id=(SELECT event_id FROM management_capture_context) AND kind='discovery_runs' AND (SELECT COUNT(*) FROM management_capture_rows WHERE event_id=management_capture_totals.event_id)>=256 AND NOT EXISTS(SELECT 1 FROM management_capture_rows WHERE event_id=management_capture_totals.event_id AND kind='discovery_runs' AND target_id=CAST(COALESCE(NEW.operation_id,'run:'||NEW.id) AS TEXT));
 INSERT INTO management_capture_rows(event_id,kind,target_id,before_json,after_json,facts_json)
 SELECT event_id,'discovery_runs',CAST(COALESCE(NEW.operation_id,'run:'||NEW.id) AS TEXT),NULL,json_object('$name',substr(COALESCE(CAST('Model discovery '||COALESCE(NEW.operation_id,'run:'||NEW.id) AS TEXT),''),1,512),'state',substr(CAST(NEW.state AS TEXT),1,512),'safe_class',substr(CAST(NEW.safe_class AS TEXT),1,512),'model_count',substr(CAST(NEW.model_count AS TEXT),1,512),'result_generation',substr(CAST(NEW.result_generation AS TEXT),1,512)),json_patch('{}',json_object()) FROM management_capture_context WHERE id=1
 AND ((SELECT COUNT(*) FROM management_capture_rows WHERE event_id=management_capture_context.event_id)<256 OR EXISTS(SELECT 1 FROM management_capture_rows WHERE event_id=management_capture_context.event_id AND kind='discovery_runs' AND target_id=CAST(COALESCE(NEW.operation_id,'run:'||NEW.id) AS TEXT)))
 ON CONFLICT(event_id,kind,target_id) DO UPDATE SET after_json=excluded.after_json,facts_json=json_patch(facts_json,excluded.facts_json);
END;

