CREATE TRIGGER management_capture_discord_blacklist_insert AFTER INSERT ON discord_blacklist
WHEN EXISTS(SELECT 1 FROM management_capture_context)
BEGIN
 INSERT INTO management_capture_totals(event_id,kind,created) SELECT event_id,'discord_blacklist',1 FROM management_capture_context WHERE id=1
 ON CONFLICT(event_id,kind) DO UPDATE SET created=created+1;
 UPDATE management_capture_totals SET omitted=omitted+1 WHERE event_id=(SELECT event_id FROM management_capture_context) AND kind='discord_blacklist' AND (SELECT COUNT(*) FROM management_capture_rows WHERE event_id=management_capture_totals.event_id)>=256 AND NOT EXISTS(SELECT 1 FROM management_capture_rows WHERE event_id=management_capture_totals.event_id AND kind='discord_blacklist' AND target_id=CAST(NEW.discord_id AS TEXT));
 INSERT INTO management_capture_rows(event_id,kind,target_id,before_json,after_json,facts_json)
 SELECT event_id,'discord_blacklist',CAST(NEW.discord_id AS TEXT),NULL,json_object('$name',substr(COALESCE(CAST(NEW.discord_id AS TEXT),''),1,512),'reason',substr(CAST(NEW.reason AS TEXT),1,512)),json_patch('{}',json_object()) FROM management_capture_context WHERE id=1
 AND ((SELECT COUNT(*) FROM management_capture_rows WHERE event_id=management_capture_context.event_id)<256 OR EXISTS(SELECT 1 FROM management_capture_rows WHERE event_id=management_capture_context.event_id AND kind='discord_blacklist' AND target_id=CAST(NEW.discord_id AS TEXT)))
 ON CONFLICT(event_id,kind,target_id) DO UPDATE SET after_json=excluded.after_json,facts_json=json_patch(facts_json,excluded.facts_json);
END;

CREATE TRIGGER management_capture_discord_blacklist_update BEFORE UPDATE ON discord_blacklist
WHEN EXISTS(SELECT 1 FROM management_capture_context)
BEGIN
 INSERT INTO management_capture_totals(event_id,kind,updated) SELECT event_id,'discord_blacklist',1 FROM management_capture_context WHERE id=1 AND (OLD.reason IS NOT NEW.reason)
 ON CONFLICT(event_id,kind) DO UPDATE SET updated=updated+1;
