 SELECT event_id,'ai_agent_jobs',CAST(OLD.id AS TEXT),json_object('$name',substr(COALESCE(CAST(OLD.kind||' '||OLD.id AS TEXT),''),1,512),'kind',substr(CAST(OLD.kind AS TEXT),1,512),'mode',substr(CAST(OLD.mode AS TEXT),1,512),'state',substr(CAST(OLD.state AS TEXT),1,512),'donation_id',substr(CAST(OLD.donation_id AS TEXT),1,512)),NULL,json_patch('{}',json_object()) FROM management_capture_context WHERE id=1
 AND ((SELECT COUNT(*) FROM management_capture_rows WHERE event_id=management_capture_context.event_id)<256 OR EXISTS(SELECT 1 FROM management_capture_rows WHERE event_id=management_capture_context.event_id AND kind='ai_agent_jobs' AND target_id=CAST(OLD.id AS TEXT)))
 ON CONFLICT(event_id,kind,target_id) DO UPDATE SET after_json=excluded.after_json,facts_json=json_patch(facts_json,excluded.facts_json);
END;
